+public class SortStatistics {
+    private final long startTime;
+    private long endTime;
+    private long comparisons;
+    private long swaps;
+
+    public SortStatistics() {
+        this.startTime = System.nanoTime();
+        this.comparisons = 0;
+        this.swaps = 0;
