+
+    public void recordComparison() {
+        this.comparisons++;
+    }
+
+    public void recordSwap() {
+        this.swaps++;
+    }
+
+    public void end() {
+        this.endTime = System.nanoTime();
+    }
+
+    public long getDurationNanos() {
+        return endTime - startTime;
+    }
+
+    public long getComparisons() {
+        return comparisons;
+    }
+
+    public long getSwaps() {
+        return swaps;
